//! Table tests of `AND` and `OR`: the collection is read item by item up to the deciding item, and
//! the cost is of the items read. sigmastate's `AND.eval` / `OR.eval` (v6.0.6 `trees.scala:269-283`,
//! `:199-213`) cast the input to `sigma.Coll` and run
//! `while (i < len && <undecided>) { res = res op inputV(i); i += 1 }` inside `addSeqCost`, whose
//! block returns the number of items processed: an item is unboxed to a Boolean where the loop
//! reads it, an item after the deciding one is never read, and a throw inside the loop has added
//! nothing of the node's own cost. The rows are sigma-state 6.0.7's at activated version 3; below
//! tree version 3 its answers at activated version 2 are the same (queue item 41's `measure/`,
//! generated by `measure/tests/gen_table.py`)
#![allow(clippy::unwrap_used)]

use crate::eval::test_util::{eval_body_at, innermost, jvm_text};
use crate::eval::EvalError;
use crate::eval::{Env, Evaluable};
use ergotree_ir::chain::context::Context;
use ergotree_ir::ergo_tree::ErgoTreeVersion;
use ergotree_ir::mir::expr::Expr;
use ergotree_ir::mir::value::Value;
use ergotree_ir::serialization::sigma_byte_reader::from_bytes;
use ergotree_ir::serialization::sigma_byte_reader::SigmaByteRead;
use ergotree_ir::serialization::SigmaSerializable;
use sigma_test_util::force_any_val;

/// A row: its name in the round's row sets, the expression's bytes, the tree version, what the
/// jars answer, and the cost counter. The answer is the value as `jvm_text` prints it, or `NOCOLL`
/// (the input is no collection: `EvalError::UnexpectedValue`; `NOCOLL <value>` when the refusal's
/// whole text is held), `ITEM` (an item
/// the loop read is no Boolean: `UnexpectedValue`; `ITEM <value>` when the refusal names that
/// value), or `ERR` for any other error
type Row = (&'static str, &'static str, u8, &'static str, u64);

/// Whether `e` is the refusal of a value of another kind whose text starts with `start`
fn refused_with(e: &EvalError, start: &str) -> bool {
    matches!(innermost(e), EvalError::UnexpectedValue(t) if t.starts_with(start))
}

/// A row under a JIT cost limit: its name in the review's row set, the expression's bytes, the
/// tree version, the limit, the answer (`LIMIT`: a cost error) and the cost counter
type LimitRow = (&'static str, &'static str, u8, u64, &'static str, u64);

/// `eval_body_at` under a JIT cost limit
fn eval_under(
    body: &str,
    version: ErgoTreeVersion,
    activated: i8,
    limit: u64,
) -> (Result<Value<'static>, EvalError>, u64) {
    let bytes = base16::decode(body.as_bytes()).unwrap();
    let expr = from_bytes(&bytes)
        .with_tree_version(version, Expr::sigma_parse)
        .unwrap();
    let mut ctx = force_any_val::<Context>();
    ctx.activated_script_version_byte = activated;
    ctx.tree_version.set(version);
    ctx.jit_cost.set(0);
    ctx.jit_cost_limit = Some(limit);
    let res = expr.eval(&mut Env::empty(), &ctx).map(|v| v.to_static());
    (res, ctx.jit_cost_value())
}

/// What is wrong with one row at one activated version, if anything: its outcome, its value or
/// its cost counter is not the table's
fn wrong(
    name: &str,
    body: &str,
    version: u8,
    limit: Option<u64>,
    expected: &str,
    cost: u64,
    activated: i8,
) -> Option<alloc::string::String> {
    let version = ErgoTreeVersion::from(version);
    let (res, stopped_at) = match limit {
        Some(limit) => eval_under(body, version, activated, limit),
        None => eval_body_at(body, version, activated),
    };
    let as_expected = match (&res, expected) {
        (Err(e), "NOCOLL") => refused_with(e, "expected a collection, found "),
        (Err(e), "ITEM") => refused_with(e, "expected a Boolean item, found "),
        (Err(e), "LIMIT") => e.is_cost_error(),
        (Err(e), named) if named.starts_with("NOCOLL ") => {
            let text = alloc::format!("expected a collection, found {}", &named[7..]);
            matches!(innermost(e), EvalError::UnexpectedValue(t) if *t == text)
        }
        (Err(_), "ERR") => true,
        (Err(e), named) if named.starts_with("ITEM ") => {
            let text = alloc::format!("expected a Boolean item, found {}", &named[5..]);
            matches!(innermost(e), EvalError::UnexpectedValue(t) if *t == text)
        }
        (Ok(v), text) => jvm_text(v) == text,
        (Err(_), _) => false,
    };
    if as_expected && stopped_at == cost {
        return None;
    }
    Some(alloc::format!(
        "{name} at activated {activated}: expected {expected} at {cost}, got {res:?} at {stopped_at}"
    ))
}

/// Both activated versions of today's blocks. The jars refuse tree version 3 at activated version
/// 2, so those rows are left out there
fn activations(version: u8) -> &'static [i8] {
    if version == 3 {
        &[3]
    } else {
        &[2, 3]
    }
}

fn check(rows: &[Row]) {
    let mut wrongs = alloc::vec::Vec::new();
    for (name, body, version, expected, cost) in rows {
        for activated in activations(*version) {
            wrongs.extend(wrong(
                name, body, *version, None, expected, *cost, *activated,
            ));
        }
    }
    assert!(
        wrongs.is_empty(),
        "{} runs of {} rows:\n{}",
        wrongs.len(),
        rows.len(),
        wrongs.join("\n")
    );
}

