#[test]
fn limits() {
    let mut wrongs = alloc::vec::Vec::new();
    for (name, body, version, limit, expected, cost) in LIMITS {
        for activated in activations(*version) {
            wrongs.extend(wrong(
                name,
                body,
                *version,
                Some(*limit),
                expected,
                *cost,
                *activated,
            ));
        }
    }
    assert!(
        wrongs.is_empty(),
        "{} runs of {} rows:\n{}",
        wrongs.len(),
        LIMITS.len(),
        wrongs.join("\n")
    );
}
